const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) return true;
const container = document.getElementById('burst-container');
if (!container) return false;

let live = document.querySelector('[data-ai4a11y-ui][aria-live]');
let count = 0;
let lastText = (live?.textContent || '').trim();

const mo = new MutationObserver(() => {
  live = document.querySelector('[data-ai4a11y-ui][aria-live]');
  const t = (live?.textContent || '').trim();
  if (t && t !== lastText) {
    count++;
    lastText = t;
  }
});
mo.observe(document.body, { childList: true, characterData: true, subtree: true });

for (let i = 0; i < 20; i++) {
  const div = document.createElement('div');
  div.className = 'status-item message';
  div.textContent = 'Batch update record ' + i;
  container.appendChild(div);
}

await new Promise((r) => setTimeout(r, 600));
mo.disconnect();
container.innerHTML = '';

return count >= 1 && count <= 3;

